     3→#include "GamePlay/TreasureChest/WjWorldTreasureChestActor.h"
     4→#include "Components/BoxComponent.h"
     5→#include "Components/StaticMeshComponent.h"
     6→#include "Components/WidgetComponent.h"
     7→#include "EnhancedInputComponent.h"
     8→#include "InputAction.h"
     9→#include "GameFramework/Character.h"
    10→#include "GameFramework/PlayerController.h"
    11→#include "Currency/WjWorldCurrencySubsystem.h"
    12→#include "Currency/WjWorldCurrencyTypes.h"
    13→#include "Setting/WjWorldDeveloperSettings.h"
    14→#include "UI/Interact/InteractionWidget.h"
    15→#include "Materials/MaterialInstanceDynamic.h"
    16→#include "Cosmetic/WjWorldCosmeticSubsystem.h"
    17→#include "WjWorldLogCategories.h"
    18→
    19→#if WITH_STEAM
    20→#include "steam/steam_api.h"
    21→#endif
    22→
    23→const FString AWjWorldTreasureChestActor::ConfigSection = TEXT("TreasureChestCooldown");
    24→
    25→AWjWorldTreasureChestActor::AWjWorldTreasureChestActor()
    26→{
    27→	PrimaryActorTick.bCanEverTick = true;
    28→	PrimaryActorTick.bStartWithTickEnabled = false;
    29→
    30→	// 뚜껑 메시
    31→	LidMeshComponent = CreateDefaultSubobject<UStaticMeshComponent>(TEXT("LidMeshComponent"));
    32→	LidMeshComponent->SetupAttachment(MeshComponent);
    33→	LidMeshComponent->SetRelativeLocation(FVector(0.0f, -60.0f, -60.0f));
    34→	LidMeshComponent->SetCollisionEnabled(ECollisionEnabled::NoCollision);
    35→
    36→	// 상호작용 트리거
    37→	InteractionTrigger = CreateDefaultSubobject<UBoxComponent>(TEXT("InteractionTrigger"));
    38→	InteractionTrigger->SetupAttachment(MeshComponent);
    39→	InteractionTrigger->SetBoxExtent(FVector(150.0f, 150.0f, 100.0f));
    40→	InteractionTrigger->SetCollisionEnabled(ECollisionEnabled::QueryOnly);
    41→	InteractionTrigger->SetCollisionResponseToAllChannels(ECR_Ignore);
    42→	InteractionTrigger->SetCollisionResponseToChannel(ECC_Pawn, ECR_Overlap);
    43→
    44→	// 위젯 컴포넌트
    45→	InteractionWidgetComponent = CreateDefaultSubobject<UWidgetComponent>(TEXT("InteractionWidget"));
    46→	InteractionWidgetComponent->SetupAttachment(MeshComponent);
    47→	InteractionWidgetComponent->SetRelativeLocation(FVector(0.0f, 0.0f, 100.0f));
    48→	InteractionWidgetComponent->SetWidgetSpace(EWidgetSpace::Screen);
    49→	InteractionWidgetComponent->SetDrawSize(FVector2D(300.0f, 60.0f));
    50→	InteractionWidgetComponent->SetVisibility(false);
    51→}
    52→
    53→void AWjWorldTreasureChestActor::BeginPlay()
    54→{
    55→	Super::BeginPlay();
    56→
    57→	// 오버랩 이벤트 바인딩
    58→	if (InteractionTrigger)
    59→	{
    60→		InteractionTrigger->OnComponentBeginOverlap.AddDynamic(this, &AWjWorldTreasureChestActor::OnTriggerBeginOverlap);
    61→		InteractionTrigger->OnComponentEndOverlap.AddDynamic(this, &AWjWorldTreasureChestActor::OnTriggerEndOverlap);
    62→	}
    63→
    64→	// UI 위젯 설정
    65→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
    66→	if (Settings && !Settings->TreasureChestWidgetClass.IsNull())
    67→	{
    68→		UClass* WidgetClass = Settings->TreasureChestWidgetClass.LoadSynchronous();
    69→		if (WidgetClass && InteractionWidgetComponent)
    70→		{
    71→			InteractionWidget = Cast<UInteractionWidget>(CreateWidget<UUserWidget>(GetWorld(), WidgetClass));
    72→			if (InteractionWidget)
    73→			{
    74→				InteractionWidgetComponent->SetWidget(InteractionWidget);
    75→			}
    76→		}
    77→	}
    78→
    79→	// 쿨타임 비주얼 초기화
    80→	if (IsOnCooldown())
    81→	{
    82→		ApplyCooldownVisual();
    83→		SetLidOpenImmediate();
    84→	}
    85→	else
    86→	{
    87→		SetLidCloseImmediate();
    88→	}
    89→}
    90→
    91→void AWjWorldTreasureChestActor::EndPlay(const EEndPlayReason::Type EndPlayReason)
    92→{
    93→	// 입력 해제
    94→	if (InteractingPlayer)
    95→	{
    96→		APlayerController* PC = Cast<APlayerController>(InteractingPlayer->GetController());
    97→		if (PC)
    98→		{
    99→			DisableInput(PC);
   100→		}
   101→	}
   102→
   103→	Super::EndPlay(EndPlayReason);
   104→}
   105→
   106→void AWjWorldTreasureChestActor::Tick(float DeltaTime)
   107→{
   108→	Super::Tick(DeltaTime);
   109→
   110→	if (!bLidAnimating || !LidMeshComponent)
   111→	{
   112→		SetActorTickEnabled(false);
   113→		bLidAnimating = false;
   114→		return;
   115→	}
   116→
   117→	float TargetRoll = bLidOpening ? LidOpenedRoll : LidClosedRoll;
   118→	float Direction = (TargetRoll > LidCurrentRoll) ? 1.0f : -1.0f;
   119→	LidCurrentRoll += Direction * LidAnimSpeed * DeltaTime;
   120→
   121→	// 목표 도달 확인
   122→	bool bReached = (Direction > 0.0f)
   123→		? (LidCurrentRoll >= TargetRoll)
   124→		: (LidCurrentRoll <= TargetRoll);
   125→
   126→	if (bReached)
   127→	{
   128→		LidCurrentRoll = TargetRoll;
   129→		bLidAnimating = false;
   130→		SetActorTickEnabled(false);
   131→	}
   132→
   133→	FRotator LidRot = LidMeshComponent->GetRelativeRotation();
   134→	LidRot.Roll = LidCurrentRoll;
   135→	LidMeshComponent->SetRelativeRotation(LidRot);
   136→}
   137→
   138→void AWjWorldTreasureChestActor::OnTriggerBeginOverlap(UPrimitiveComponent* OverlappedComponent, AActor* OtherActor,
   139→	UPrimitiveComponent* OtherComp, int32 OtherBodyIndex, bool bFromSweep, const FHitResult& SweepResult)
   140→{
   141→	APawn* Pawn = Cast<APawn>(OtherActor);
   142→	if (!Pawn || !Pawn->IsPlayerControlled())
   143→	{
   144→		return;
   145→	}
   146→
   147→	bPlayerInRange = true;
   148→	InteractingPlayer = Pawn;
   149→
   150→	// 입력 바인딩
   151→	APlayerController* PC = Cast<APlayerController>(Pawn->GetController());
   152→	if (PC)
   153→	{
   154→		EnableInput(PC);
   155→
   156→		const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   157→		if (Settings && InputComponent)
   158→		{
   159→			UInputAction* IA = Settings->TreasureChestInteractAction.LoadSynchronous();
   160→			if (IA)
   161→			{
   162→				if (UEnhancedInputComponent* EIC = Cast<UEnhancedInputComponent>(InputComponent))
   163→				{
   164→					EIC->BindAction(IA, ETriggerEvent::Started, this, &AWjWorldTreasureChestActor::OnInteract);
   165→				}
   166→			}
   167→		}
   168→	}
   169→
   170→	ShowInteractionUI();
   171→
   172→	UE_LOG(LogWjWorld, Log, TEXT("TreasureChest: Player entered range"));
   173→}
   174→
   175→void AWjWorldTreasureChestActor::OnTriggerEndOverlap(UPrimitiveComponent* OverlappedComponent, AActor* OtherActor,
   176→	UPrimitiveComponent* OtherComp, int32 OtherBodyIndex)
   177→{
   178→	APawn* Pawn = Cast<APawn>(OtherActor);
   179→	if (!Pawn || !Pawn->IsPlayerControlled())
   180→	{
   181→		return;
   182→	}
   183→
   184→	// 입력 해제
   185→	APlayerController* PC = Cast<APlayerController>(Pawn->GetController());
   186→	if (PC)
   187→	{
   188→		DisableInput(PC);
   189→	}
   190→
   191→	bPlayerInRange = false;
   192→	InteractingPlayer = nullptr;
   193→
   194→	HideInteractionUI();
   195→
   196→	UE_LOG(LogWjWorld, Log, TEXT("TreasureChest: Player left range"));
   197→}
   198→
   199→void AWjWorldTreasureChestActor::OnInteract()
   200→{
   201→	if (!bPlayerInRange || !InteractingPlayer)
   202→	{
   203→		return;
   204→	}
   205→
   206→	// 로컬 쿨타임 확인 (UI용, Steam에서는 서버도 이중 검증)
   207→	if (IsOnCooldown())
   208→	{
   209→		UE_LOG(LogWjWorld, Log, TEXT("TreasureChest: On cooldown, remaining: %s"),
   210→			*GetRemainingCooldown().ToString());
   211→		return;
   212→	}
   213→
   214→	// 보상 지급 시도
   215→	if (!TryGrantReward())
   216→	{
   217→		UE_LOG(LogWjWorld, Log, TEXT("TreasureChest: Reward grant failed (Steam cooldown or error)"));
   218→		return;
   219→	}
   220→
   221→	// 쿨타임 타임스탬프 저장 (UI 표시용)
   222→	SaveCooldown();
   223→
   224→	// 뚜껑 열기 연출
   225→	PlayLidOpen();
   226→
   227→	// 비주얼 전환
   228→	ApplyCooldownVisual();
   229→
   230→	// UI 갱신
   231→	UpdateInteractionUI();
   232→}
   233→
   234→bool AWjWorldTreasureChestActor::TryGrantReward()
   235→{
   236→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   237→	if (!Settings)
   238→	{
   239→		return false;
   240→	}
   241→
   242→#if WITH_STEAM
   243→	ISteamInventory* SteamInv = SteamInventory();
   244→	if (SteamInv)
   245→	{
   246→		SteamInventoryResult_t ResultHandle = k_SteamInventoryResultInvalid;
   247→		int32 GeneratorDefId = Settings->TreasureChestGeneratorStartDefId + ChestIndex;
   248→		SteamItemDef_t DropDef = static_cast<SteamItemDef_t>(GeneratorDefId);
   249→
   250→		if (SteamInv->TriggerItemDrop(&ResultHandle, DropDef))
   251→		{
   252→			// 결과 상태 확인 (캐시된 경우 즉시 반환)
   253→			EResult Status = SteamInv->GetResultStatus(ResultHandle);
   254→			SteamInv->DestroyResult(ResultHandle);
   255→
   256→			if (Status == k_EResultOK)
   257→			{
   258→				UE_LOG(LogWjWorldCurrency, Log, TEXT("TreasureChest[%d]: Steam TriggerItemDrop 성공 (DefId: %d)"),
   259→					ChestIndex, GeneratorDefId);
   260→
   261→				// 인벤토리 갱신으로 잔액 반영
   262→				UGameInstance* GI = GetGameInstance();
   263→				if (GI)
   264→				{
   265→					UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   266→					if (CosmeticSub)
   267→					{
   268→						CosmeticSub->RequestInventoryRefresh();
   269→					}
   270→				}
   271→
   272→				return true;
   273→			}
   274→			else
   275→			{
   276→				UE_LOG(LogWjWorldCurrency, Log, TEXT("TreasureChest[%d]: Steam TriggerItemDrop 쿨타임 또는 실패 (DefId: %d, Status: %d)"),
   277→					ChestIndex, GeneratorDefId, static_cast<int32>(Status));
   278→				return false;
   279→			}
   280→		}
   281→		else
   282→		{
   283→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("TreasureChest[%d]: Steam TriggerItemDrop 호출 실패 (DefId: %d)"),
   284→				ChestIndex, GeneratorDefId);
   285→			return false;
   286→		}
   287→	}
   288→#endif
   289→
   290→	// 비Steam 폴백: 로컬 재화 부여
   291→	int32 RewardAmount = Settings->TreasureChestCoinReward;
   292→	UGameInstance* GI = GetGameInstance();
   293→	if (GI)
   294→	{
   295→		UWjWorldCurrencySubsystem* CurrencySub = GI->GetSubsystem<UWjWorldCurrencySubsystem>();
   296→		if (CurrencySub)
   297→		{
   298→			CurrencySub->GrantCurrencyLocally(ECurrencyType::Coin, RewardAmount);
   299→			UE_LOG(LogWjWorldCurrency, Log, TEXT("TreasureChest: 로컬 보상 %d Coin 지급"), RewardAmount);
   300→		}
   301→	}
   302→
   303→	return true;
   304→}
   305→
   306→void AWjWorldTreasureChestActor::ShowInteractionUI()
   307→{
   308→	if (InteractionWidgetComponent)
   309→	{
   310→		InteractionWidgetComponent->SetVisibility(true);
   311→		UpdateInteractionUI();
   312→	}
   313→}
   314→
   315→void AWjWorldTreasureChestActor::HideInteractionUI()
   316→{
   317→	if (InteractionWidgetComponent)
   318→	{
   319→		InteractionWidgetComponent->SetVisibility(false);
   320→	}
   321→}
   322→
   323→void AWjWorldTreasureChestActor::UpdateInteractionUI()
   324→{
   325→	if (!InteractionWidget)
   326→	{
   327→		return;
   328→	}
   329→
   330→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   331→	int32 RewardAmount = Settings ? Settings->TreasureChestCoinReward : 50;
   332→
   333→	if (IsOnCooldown())
   334→	{
   335→		FTimespan Remaining = GetRemainingCooldown();
   336→		int32 Hours = static_cast<int32>(Remaining.GetTotalHours());
   337→		int32 Minutes = Remaining.GetMinutes();
   338→		int32 Seconds = Remaining.GetSeconds();
