    18→	if (Settings && !Settings->CosmeticCatalog.IsNull())
    19→	{
    20→		Catalog = Settings->CosmeticCatalog.LoadSynchronous();
    21→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("카탈로그 로드: %s"), Catalog ? *Catalog->GetName() : TEXT("실패"));
    22→	}
    23→	else
    24→	{
    25→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("DeveloperSettings에 CosmeticCatalog가 설정되지 않았습니다."));
    26→	}
    27→
    28→	LoadLoadoutFromLocal();
    29→
    30→	// Steam 인벤토리 초기 로드
    31→	RequestInventoryRefresh();
    32→
    33→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticSubsystem 초기화 완료"));
    34→}
