   138→bool UWjWorldCosmeticSubsystem::EquipItem(ECosmeticSlot Slot, FName ItemId)
   139→{
   140→	if (Slot == ECosmeticSlot::None)
   141→	{
   142→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("None 슬롯에 장착할 수 없습니다."));
   143→		return false;
   144→	}
   145→
   146→	if (!HasItem(ItemId))
   147→	{
   148→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("아이템 '%s'을 보유하고 있지 않습니다."), *ItemId.ToString());
   149→		return false;
   150→	}
   151→
   152→	// 카탈로그 검증: 슬롯 일치 확인
   153→	if (Catalog)
   154→	{
   155→		const FCosmeticItemDefinition* Def = Catalog->FindByItemId(ItemId);
   156→		if (Def && Def->Slot != Slot)
   157→		{
   158→			UE_LOG(LogWjWorldCosmetic, Warning, TEXT("아이템 '%s'은 슬롯 %d에 장착할 수 없습니다 (정의된 슬롯: %d)."),
   159→				*ItemId.ToString(), static_cast<int32>(Slot), static_cast<int32>(Def->Slot));
   160→			return false;
   161→		}
   162→	}
   163→
   164→	CurrentLoadout.Equip(Slot, ItemId);
   165→	SaveLoadoutToLocal();
   166→	OnLoadoutChanged.Broadcast(Slot, ItemId);
   167→
   168→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("장착: 슬롯 %d ← %s"), static_cast<int32>(Slot), *ItemId.ToString());
   169→	return true;
   170→}
