   181→void UWjWorldCosmeticSubsystem::SaveLoadoutToLocal()
   182→{
   183→	FString ConfigFilePath = FPaths::GeneratedConfigDir() + TEXT("CosmeticLoadout.ini");
   184→
   185→	for (const FCosmeticSlotEntry& Entry : CurrentLoadout.Entries)
   186→	{
   187→		FString SlotKey = FString::Printf(TEXT("Slot_%d"), static_cast<int32>(Entry.Slot));
   188→		GConfig->SetString(*LoadoutConfigSection, *SlotKey, *Entry.ItemId.ToString(), ConfigFilePath);
   189→	}
   190→
   191→	GConfig->Flush(false, ConfigFilePath);
   192→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("로드아웃 로컬 저장 완료"));
