   195→void UWjWorldCosmeticSubsystem::LoadLoadoutFromLocal()
   196→{
   197→	FString ConfigFilePath = FPaths::GeneratedConfigDir() + TEXT("CosmeticLoadout.ini");
   198→
   199→	CurrentLoadout.Reset();
   200→
   201→	for (int32 SlotIdx = static_cast<int32>(ECosmeticSlot::Head);
   202→		SlotIdx <= static_cast<int32>(ECosmeticSlot::Effect); ++SlotIdx)
   203→	{
   204→		FString SlotKey = FString::Printf(TEXT("Slot_%d"), SlotIdx);
   205→		FString ItemIdStr;
   206→		if (GConfig->GetString(*LoadoutConfigSection, *SlotKey, ItemIdStr, ConfigFilePath))
   207→		{
   208→			if (!ItemIdStr.IsEmpty())
   209→			{
   210→				CurrentLoadout.Equip(static_cast<ECosmeticSlot>(SlotIdx), FName(*ItemIdStr));
   211→			}
   212→		}
   213→	}
   214→
   215→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("로드아웃 로컬 로드 완료 (%d 슬롯)"), CurrentLoadout.Entries.Num());
