   443→bool UWjWorldCosmeticSubsystem::GenerateTestItem(FName ItemId)
   444→{
   445→#if WITH_STEAM && !UE_BUILD_SHIPPING
   446→	if (ItemId.IsNone())
   447→	{
   448→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("GenerateTestItem: 유효하지 않은 ItemId"));
   449→		return false;
   450→	}
   451→
   452→	ISteamInventory* SteamInv = SteamInventory();
   453→	if (!SteamInv)
   454→	{
   455→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("GenerateTestItem: Steam Inventory API 사용 불가"));
   456→		return false;
   457→	}
   458→
   459→	if (!Catalog)
   460→	{
   461→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("GenerateTestItem: 카탈로그 없음"));
   462→		return false;
   463→	}
   464→
   465→	int32 SteamDefId = Catalog->ItemIdToSteamItemDefId(ItemId);
   466→	if (SteamDefId == 0)
   467→	{
   468→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("GenerateTestItem: SteamItemDefId를 찾을 수 없음 (%s)"), *ItemId.ToString());
   469→		return false;
   470→	}
   471→
   472→	SteamItemDef_t ItemDef = static_cast<SteamItemDef_t>(SteamDefId);
   473→	uint32 Quantity = 1;
   474→	SteamInventoryResult_t ResultHandle = k_SteamInventoryResultInvalid;
   475→
   476→	if (SteamInv->GenerateItems(&ResultHandle, &ItemDef, &Quantity, 1))
   477→	{
   478→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("GenerateTestItem: 테스트 아이템 생성 요청 성공 (%s, DefId: %d)"), *ItemId.ToString(), SteamDefId);
   479→
   480→		// 결과 핸들 정리 (비동기이므로 즉시 파괴하면 안됨 - 실제 구현시 폴링 필요)
   481→		// 간단한 테스트를 위해 로컬 인벤토리에도 추가
   482→		GrantItemLocally(ItemId, 1);
   483→
   484→		SteamInv->DestroyResult(ResultHandle);
   485→		return true;
   486→	}
   487→	else
   488→	{
   489→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("GenerateTestItem: Steam GenerateItems 실패"));
   490→		return false;
   491→	}
   492→#else
   493→	// 비 Steam 또는 Shipping 빌드: 로컬로 아이템 부여
   494→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("GenerateTestItem: 로컬 아이템 부여 (비Steam 환경) - %s"), *ItemId.ToString());
   495→	GrantItemLocally(ItemId, 1);
   496→	return true;
   497→#endif
   498→}
