   368→int32 UWjWorldCurrencySubsystem::GetItemQuantityFromInventory(int32 SteamItemDefId) const
   369→{
   370→	// CosmeticSubsystem의 캐시된 인벤토리에서 해당 DefId의 수량을 찾음
   371→	// 재화 아이템은 CosmeticCatalog에 등록되어 있지 않으므로
   372→	// CosmeticSubsystem의 파싱에서 "알 수 없는 SteamItemDefId"로 스킵됨
   373→	// 따라서 별도의 Steam Inventory 조회가 필요
   374→
   375→	// 현재는 CosmeticSubsystem의 인벤토리 갱신 시점에 호출되므로
   376→	// 직접 Steam API를 호출하여 확인
   377→#if WITH_STEAM
   378→	ISteamInventory* SteamInv = SteamInventory();
   379→	if (!SteamInv)
   380→	{
   381→		return 0;
   382→	}
   383→
   384→	SteamInventoryResult_t ResultHandle = k_SteamInventoryResultInvalid;
   385→	if (!SteamInv->GetAllItems(&ResultHandle))
   386→	{
   387→		return 0;
   388→	}
   389→
   390→	// 결과 대기 (동기적 폴링 - 이미 캐시된 경우 즉시 반환)
   391→	// 참고: GetAllItems는 이전에 성공한 결과가 캐시되어 있으면 즉시 반환됨
   392→	int32 TotalQuantity = 0;
   393→
   394→	EResult Status = SteamInv->GetResultStatus(ResultHandle);
   395→	if (Status == k_EResultOK)
   396→	{
   397→		uint32 ItemCount = 0;
   398→		if (SteamInv->GetResultItems(ResultHandle, nullptr, &ItemCount) && ItemCount > 0)
   399→		{
   400→			TArray<SteamItemDetails_t> ItemDetails;
   401→			ItemDetails.SetNum(ItemCount);
   402→
   403→			if (SteamInv->GetResultItems(ResultHandle, ItemDetails.GetData(), &ItemCount))
   404→			{
   405→				for (uint32 i = 0; i < ItemCount; ++i)
   406→				{
   407→					if (ItemDetails[i].m_iDefinition == SteamItemDefId && ItemDetails[i].m_unQuantity > 0)
   408→					{
   409→						TotalQuantity += ItemDetails[i].m_unQuantity;
   410→					}
   411→				}
   412→			}
   413→		}
   414→	}
   415→
   416→	SteamInv->DestroyResult(ResultHandle);
   417→	return TotalQuantity;
   418→#else
   419→	return 0;
   420→#endif
   421→}
