   590→	GemBalance = FMath::Max(0, LoadedGem);
   591→
   592→	UE_LOG(LogWjWorldCurrency, Log, TEXT("재화 잔액 로컬 로드 완료 (Coin: %d, Gem: %d)"), CoinBalance, GemBalance);
