   106→void AWjWorldTreasureChestActor::Tick(float DeltaTime)
   107→{
   108→	Super::Tick(DeltaTime);
   109→
   110→	if (!bLidAnimating || !LidMeshComponent)
   111→	{
   112→		SetActorTickEnabled(false);
   113→		bLidAnimating = false;
   114→		return;
   115→	}
   116→
   117→	float TargetRoll = bLidOpening ? LidOpenedRoll : LidClosedRoll;
   118→	float Direction = (TargetRoll > LidCurrentRoll) ? 1.0f : -1.0f;
   119→	LidCurrentRoll += Direction * LidAnimSpeed * DeltaTime;
   120→
   121→	// 목표 도달 확인
   122→	bool bReached = (Direction > 0.0f)
   123→		? (LidCurrentRoll >= TargetRoll)
   124→		: (LidCurrentRoll <= TargetRoll);
   125→
   126→	if (bReached)
   127→	{
   128→		LidCurrentRoll = TargetRoll;
   129→		bLidAnimating = false;
   130→		SetActorTickEnabled(false);
   131→	}
   132→
   133→	FRotator LidRot = LidMeshComponent->GetRelativeRotation();
   134→	LidRot.Roll = LidCurrentRoll;
   135→	LidMeshComponent->SetRelativeRotation(LidRot);
   136→}
