   366→bool AWjWorldTreasureChestActor::IsOnCooldown() const
   367→{
   368→	FString Key = GetChestKey();
   369→	FString LastOpenedStr;
   370→	FString ConfigPath = GetConfigPath();
   371→
   372→	if (GConfig->GetString(*ConfigSection, *Key, LastOpenedStr, ConfigPath))
   373→	{
   374→		FDateTime LastOpened;
   375→		if (FDateTime::ParseIso8601(*LastOpenedStr, LastOpened))
   376→		{
   377→			const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   378→			float CooldownSeconds = Settings ? Settings->TreasureChestCooldownSeconds : 86400.0f;
   379→			return (FDateTime::UtcNow() - LastOpened).GetTotalSeconds() < CooldownSeconds;
   380→		}
   381→	}
   382→	return false;
   383→}
   384→
   385→FTimespan AWjWorldTreasureChestActor::GetRemainingCooldown() const
   386→{
   387→	FString Key = GetChestKey();
   388→	FString LastOpenedStr;
   389→	FString ConfigPath = GetConfigPath();
   390→
   391→	if (GConfig->GetString(*ConfigSection, *Key, LastOpenedStr, ConfigPath))
   392→	{
   393→		FDateTime LastOpened;
   394→		if (FDateTime::ParseIso8601(*LastOpenedStr, LastOpened))
   395→		{
   396→			const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   397→			float CooldownSeconds = Settings ? Settings->TreasureChestCooldownSeconds : 86400.0f;
   398→
   399→			FDateTime CooldownEnd = LastOpened + FTimespan::FromSeconds(CooldownSeconds);
   400→			FTimespan Remaining = CooldownEnd - FDateTime::UtcNow();
   401→
   402→			if (Remaining.GetTotalSeconds() > 0)
   403→			{
   404→				return Remaining;
   405→			}
   406→		}
   407→	}
   408→	return FTimespan::Zero();
   409→}
