    40→bool UWjWorldPurchaseSubsystem::RequestPurchase(FName ItemId)
    41→{
    42→	if (CurrentState == EPurchaseState::Pending)
    43→	{
    44→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("이미 구매가 진행 중입니다 (PendingItem: %s)."), *PendingItemId.ToString());
    45→		return false;
    46→	}
    47→
    48→	if (ItemId.IsNone())
    49→	{
    50→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("유효하지 않은 ItemId입니다."));
    51→		return false;
    52→	}
    53→
    54→#if WITH_STEAM
    55→	UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
    56→	if (!CosmeticSub || !CosmeticSub->GetCatalog())
    57→	{
    58→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("CosmeticSubsystem 또는 카탈로그가 없습니다."));
    59→		return false;
    60→	}
    61→
    62→	int32 SteamDefId = CosmeticSub->GetCatalog()->ItemIdToSteamItemDefId(ItemId);
    63→	if (SteamDefId == 0)
    64→	{
    65→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("아이템 '%s'에 대한 SteamItemDefId를 찾을 수 없습니다."), *ItemId.ToString());
    66→		return false;
    67→	}
    68→
    69→	ISteamInventory* SteamInv = SteamInventory();
    70→	if (!SteamInv)
    71→	{
    72→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("Steam Inventory API를 사용할 수 없습니다."));
    73→		return false;
    74→	}
    75→
    76→	// 기존 핸들 정리
    77→	if (PurchaseResultHandle != k_SteamInventoryResultInvalid)
    78→	{
    79→		SteamInv->DestroyResult(PurchaseResultHandle);
    80→		PurchaseResultHandle = k_SteamInventoryResultInvalid;
    81→	}
    82→
    83→	// Steam StartPurchase를 통해 결제 오버레이 요청
    84→	SteamItemDef_t ItemDef = static_cast<SteamItemDef_t>(SteamDefId);
    85→	uint32 Quantity = 1;
    86→
    87→	if (SteamInv->StartPurchase(&ItemDef, &Quantity, 1))
    88→	{
    89→		CurrentState = EPurchaseState::Pending;
    90→		PendingItemId = ItemId;
    91→		PurchaseStartTime = GetWorld() ? GetWorld()->GetTimeSeconds() : 0.f;
    92→		StartPurchasePolling();
    93→
    94→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("Steam 구매 요청 시작: ItemDefId=%d, ItemId=%s"), SteamDefId, *ItemId.ToString());
    95→		return true;
    96→	}
    97→	else
    98→	{
    99→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("Steam StartPurchase 실패: ItemDefId=%d"), SteamDefId);
   100→		return false;
   101→	}
   102→#else
   103→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("Steam 미지원 환경 - 구매 시뮬레이션: %s"), *ItemId.ToString());
   104→
   105→	// 비 Steam 환경에서는 즉시 성공 처리 (테스트용)
   106→	CurrentState = EPurchaseState::Pending;
   107→	PendingItemId = ItemId;
   108→	HandlePurchaseResult(true);
   109→	return true;
   110→#endif
   111→}
   112→
   113→void UWjWorldPurchaseSubsystem::HandlePurchaseResult(bool bSuccess)
   114→{
   115→	if (bSuccess)
   116→	{
   117→		CurrentState = EPurchaseState::Completed;
   118→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("구매 완료: %s"), *PendingItemId.ToString());
   119→
   120→		RefreshInventoryAfterPurchase();
   121→	}
   122→	else
   123→	{
   124→		CurrentState = EPurchaseState::Failed;
   125→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("구매 실패: %s"), *PendingItemId.ToString());
   126→	}
   127→
   128→	OnPurchaseComplete.Broadcast(PendingItemId, bSuccess);
   129→
   130→	// 상태 리셋 (다음 구매를 위해)
   131→	FName CompletedItemId = PendingItemId;
   132→	PendingItemId = NAME_None;
   133→	CurrentState = EPurchaseState::Idle;
   134→}
   135→
   136→void UWjWorldPurchaseSubsystem::RefreshInventoryAfterPurchase()
   137→{
   138→	UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   139→	if (CosmeticSub)
   140→	{
   141→#if WITH_STEAM
   142→		CosmeticSub->RequestInventoryRefresh();
   143→#else
   144→		// 비 Steam 환경: 로컬로 아이템 부여
   145→		CosmeticSub->GrantItemLocally(PendingItemId, 1);
   146→#endif
   147→	}
   148→}
   149→
   150→void UWjWorldPurchaseSubsystem::StartPurchasePolling()
   151→{
   152→	UWorld* World = GetWorld();
   153→	if (!World)
   154→	{
   155→		return;
   156→	}
   157→
   158→	// 1초 간격으로 구매 결과 폴링
   159→	World->GetTimerManager().SetTimer(
   160→		PurchasePollTimerHandle,
   161→		this,
   162→		&UWjWorldPurchaseSubsystem::PollPurchaseResult,
   163→		1.0f,
   164→		true
   165→	);
   166→
   167→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("구매 결과 폴링 시작"));
   168→}
   169→
   170→void UWjWorldPurchaseSubsystem::StopPurchasePolling()
   171→{
   172→	UWorld* World = GetWorld();
   173→	if (World)
   174→	{
   175→		World->GetTimerManager().ClearTimer(PurchasePollTimerHandle);
   176→	}
   177→
   178→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("구매 결과 폴링 중지"));
   179→}
   180→
   181→void UWjWorldPurchaseSubsystem::PollPurchaseResult()
   182→{
   183→#if WITH_STEAM
   184→	if (CurrentState != EPurchaseState::Pending)
   185→	{
   186→		StopPurchasePolling();
   187→		return;
   188→	}
   189→
   190→	// 타임아웃 체크
   191→	UWorld* World = GetWorld();
   192→	if (World)
   193→	{
   194→		float ElapsedTime = World->GetTimeSeconds() - PurchaseStartTime;
   195→		if (ElapsedTime > PurchaseTimeoutSeconds)
   196→		{
   197→			UE_LOG(LogWjWorldCosmetic, Warning, TEXT("구매 타임아웃 (%.1f초 경과)"), ElapsedTime);
   198→			HandlePurchaseResult(false);
   199→			return;
   200→		}
   201→	}
   202→
   203→	// Steam 콜백이 아닌 인벤토리 변경 체크 방식 사용
   204→	// Steam은 구매 완료 시 자동으로 인벤토리에 아이템을 추가하므로,
   205→	// 주기적으로 인벤토리를 확인하여 아이템이 추가되었는지 체크
   206→	ISteamInventory* SteamInv = SteamInventory();
   207→	if (!SteamInv)
   208→	{
   209→		HandlePurchaseResult(false);
   210→		return;
   211→	}
   212→
   213→	// 인벤토리 갱신 요청을 통해 구매 완료 여부 확인
   214→	// (실제 콜백은 CosmeticSubsystem에서 처리)
   215→	UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   216→	if (CosmeticSub && CosmeticSub->HasItem(PendingItemId))
   217→	{
   218→		// 이미 아이템을 보유하고 있으면 구매 성공
   219→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("구매 확인: 아이템 '%s' 보유 감지"), *PendingItemId.ToString());
   220→		HandlePurchaseResult(true);
   221→	}
   222→#else
   223→	StopPurchasePolling();
   224→#endif
   225→}
