   138→void AWjWorldTreasureChestActor::OnTriggerBeginOverlap(UPrimitiveComponent* OverlappedComponent, AActor* OtherActor,
   139→	UPrimitiveComponent* OtherComp, int32 OtherBodyIndex, bool bFromSweep, const FHitResult& SweepResult)
   140→{
   141→	APawn* Pawn = Cast<APawn>(OtherActor);
   142→	if (!Pawn || !Pawn->IsPlayerControlled())
   143→	{
   144→		return;
   145→	}
   146→
   147→	bPlayerInRange = true;
   148→	InteractingPlayer = Pawn;
   149→
   150→	// 입력 바인딩
   151→	APlayerController* PC = Cast<APlayerController>(Pawn->GetController());
   152→	if (PC)
   153→	{
   154→		EnableInput(PC);
   155→
   156→		const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   157→		if (Settings && InputComponent)
   158→		{
   159→			UInputAction* IA = Settings->TreasureChestInteractAction.LoadSynchronous();
   160→			if (IA)
   161→			{
   162→				if (UEnhancedInputComponent* EIC = Cast<UEnhancedInputComponent>(InputComponent))
   163→				{
   164→					EIC->BindAction(IA, ETriggerEvent::Started, this, &AWjWorldTreasureChestActor::OnInteract);
   165→				}
   166→			}
   167→		}
   168→	}
   169→
   170→	ShowInteractionUI();
   171→
   172→	UE_LOG(LogWjWorld, Log, TEXT("TreasureChest: Player entered range"));
   173→}
