   199→void AWjWorldTreasureChestActor::OnInteract()
   200→{
   201→	if (!bPlayerInRange || !InteractingPlayer)
   202→	{
   203→		return;
   204→	}
   205→
   206→	// 로컬 쿨타임 확인 (UI용, Steam에서는 서버도 이중 검증)
   207→	if (IsOnCooldown())
   208→	{
   209→		UE_LOG(LogWjWorld, Log, TEXT("TreasureChest: On cooldown, remaining: %s"),
   210→			*GetRemainingCooldown().ToString());
   211→		return;
   212→	}
   213→
   214→	// 보상 지급 시도
   215→	if (!TryGrantReward())
   216→	{
   217→		UE_LOG(LogWjWorld, Log, TEXT("TreasureChest: Reward grant failed (Steam cooldown or error)"));
   218→		return;
   219→	}
   220→
   221→	// 쿨타임 타임스탬프 저장 (UI 표시용)
   222→	SaveCooldown();
   223→
   224→	// 뚜껑 열기 연출
   225→	PlayLidOpen();
   226→
   227→	// 비주얼 전환
   228→	ApplyCooldownVisual();
   229→
   230→	// UI 갱신
   231→	UpdateInteractionUI();
   232→}
