   234→bool AWjWorldTreasureChestActor::TryGrantReward()
   235→{
   236→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   237→	if (!Settings)
   238→	{
   239→		return false;
   240→	}
   241→
   242→#if WITH_STEAM
   243→	ISteamInventory* SteamInv = SteamInventory();
   244→	if (SteamInv)
   245→	{
   246→		SteamInventoryResult_t ResultHandle = k_SteamInventoryResultInvalid;
   247→		int32 GeneratorDefId = Settings->TreasureChestGeneratorStartDefId + ChestIndex;
   248→		SteamItemDef_t DropDef = static_cast<SteamItemDef_t>(GeneratorDefId);
   249→
   250→		if (SteamInv->TriggerItemDrop(&ResultHandle, DropDef))
   251→		{
   252→			// 결과 상태 확인 (캐시된 경우 즉시 반환)
   253→			EResult Status = SteamInv->GetResultStatus(ResultHandle);
   254→			SteamInv->DestroyResult(ResultHandle);
   255→
   256→			if (Status == k_EResultOK)
   257→			{
   258→				UE_LOG(LogWjWorldCurrency, Log, TEXT("TreasureChest[%d]: Steam TriggerItemDrop 성공 (DefId: %d)"),
   259→					ChestIndex, GeneratorDefId);
   260→
   261→				// 인벤토리 갱신으로 잔액 반영
   262→				UGameInstance* GI = GetGameInstance();
   263→				if (GI)
   264→				{
   265→					UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   266→					if (CosmeticSub)
   267→					{
   268→						CosmeticSub->RequestInventoryRefresh();
   269→					}
   270→				}
   271→
   272→				return true;
   273→			}
   274→			else
   275→			{
   276→				UE_LOG(LogWjWorldCurrency, Log, TEXT("TreasureChest[%d]: Steam TriggerItemDrop 쿨타임 또는 실패 (DefId: %d, Status: %d)"),
   277→					ChestIndex, GeneratorDefId, static_cast<int32>(Status));
   278→				return false;
   279→			}
   280→		}
   281→		else
   282→		{
   283→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("TreasureChest[%d]: Steam TriggerItemDrop 호출 실패 (DefId: %d)"),
   284→				ChestIndex, GeneratorDefId);
   285→			return false;
   286→		}
   287→	}
   288→#endif
   289→
   290→	// 비Steam 폴백: 로컬 재화 부여
   291→	int32 RewardAmount = Settings->TreasureChestCoinReward;
   292→	UGameInstance* GI = GetGameInstance();
   293→	if (GI)
   294→	{
   295→		UWjWorldCurrencySubsystem* CurrencySub = GI->GetSubsystem<UWjWorldCurrencySubsystem>();
   296→		if (CurrencySub)
   297→		{
   298→			CurrencySub->GrantCurrencyLocally(ECurrencyType::Coin, RewardAmount);
   299→			UE_LOG(LogWjWorldCurrency, Log, TEXT("TreasureChest: 로컬 보상 %d Coin 지급"), RewardAmount);
   300→		}
   301→	}
   302→
   303→	return true;
   304→}
