    30→void UWjWorldStatsSubsystem::RequestCurrentStats()
    31→{
    32→#if WITH_STEAM
    33→	ISteamUserStats* SteamStats = ::SteamUserStats();
    34→	if (SteamStats)
    35→	{
    36→		// Steamworks v161: RequestCurrentStats()가 제거됨
    37→		// Steam 클라이언트가 자동으로 스탯을 동기화하므로 즉시 사용 가능
    38→		bLocalStatsLoaded = true;
    39→
    40→		// 로컬 캐시 업데이트
    41→		const TArray<FMinigameStatDescriptor>& Descriptors = GetAllMinigameDescriptors();
    42→		for (const FMinigameStatDescriptor& Desc : Descriptors)
    43→		{
    44→			for (const FMinigameStatEntry& Entry : Desc.Stats)
    45→			{
    46→				int32 Value = 0;
    47→				SteamStats->GetStat(TCHAR_TO_UTF8(*Entry.StatName.ToString()), &Value);
    48→				LocalStats.Add(Entry.StatName, Value);
    49→			}
    50→		}
    51→
    52→		OnLocalStatsReady.Broadcast();
    53→		UE_LOG(LogWjWorldStats, Log, TEXT("StatsSubsystem: Steam stats loaded (auto-synced by client)"));
    54→	}
    55→	else
    56→	{
    57→		// Steam 초기화 안 됨 - 폴백
    58→		LoadLocalStatsFromConfig();
    59→		OnLocalStatsReady.Broadcast();
    60→	}
    61→#else
    62→	LoadLocalStatsFromConfig();
    63→	OnLocalStatsReady.Broadcast();
    64→	UE_LOG(LogWjWorldStats, Log, TEXT("StatsSubsystem: Loaded local stats from config (non-Steam)"));
    65→#endif
    66→}
    67→
    68→int32 UWjWorldStatsSubsystem::GetLocalStat(FName StatName) const
    69→{
    70→#if WITH_STEAM
    71→	ISteamUserStats* SteamStats = ::SteamUserStats();
    72→	if (SteamStats && bLocalStatsLoaded)
    73→	{
    74→		int32 Value = 0;
    75→		if (SteamStats->GetStat(TCHAR_TO_UTF8(*StatName.ToString()), &Value))
    76→		{
    77→			return Value;
    78→		}
    79→	}
    80→	// 폴백
    81→#endif
    82→
    83→	const int32* Found = LocalStats.Find(StatName);
    84→	return Found ? *Found : 0;
    85→}
    86→
    87→void UWjWorldStatsSubsystem::IncrementLocalStat(FName StatName, int32 Delta)
    88→{
    89→	int32 CurrentValue = GetLocalStat(StatName);
    90→	int32 NewValue = CurrentValue + Delta;
    91→
    92→#if WITH_STEAM
    93→	ISteamUserStats* SteamStats = ::SteamUserStats();
    94→	if (SteamStats && bLocalStatsLoaded)
    95→	{
    96→		SteamStats->SetStat(TCHAR_TO_UTF8(*StatName.ToString()), NewValue);
    97→	}
    98→#endif
    99→
   100→	LocalStats.FindOrAdd(StatName) = NewValue;
   101→
   102→	UE_LOG(LogWjWorldStats, Log, TEXT("StatsSubsystem: %s incremented %d -> %d"), *StatName.ToString(), CurrentValue, NewValue);
   103→}
