   105→void UWjWorldStatsSubsystem::StoreStats()
   106→{
   107→#if WITH_STEAM
   108→	ISteamUserStats* SteamStats = ::SteamUserStats();
   109→	if (SteamStats && bLocalStatsLoaded)
   110→	{
   111→		SteamStats->StoreStats();
   112→		UE_LOG(LogWjWorldStats, Log, TEXT("StatsSubsystem: StoreStats called (Steam)"));
   113→		return;
   114→	}
   115→#endif
   116→
   117→	SaveLocalStatsToConfig();
   118→	UE_LOG(LogWjWorldStats, Log, TEXT("StatsSubsystem: StoreStats called (config fallback)"));
