   121→void UWjWorldStatsSubsystem::RequestUserStats(const FUniqueNetIdRepl& UserId)
   122→{
   123→	if (!UserId.IsValid())
   124→	{
   125→		return;
   126→	}
   127→
   128→	FString UserIdStr = UserId.ToString();
   129→
   130→#if WITH_STEAM
   131→	ISteamUserStats* SteamStats = ::SteamUserStats();
   132→	if (SteamStats)
   133→	{
   134→		// FUniqueNetIdRepl에서 CSteamID 추출
   135→		uint64 SteamId64 = FCString::Atoi64(*UserIdStr);
   136→		CSteamID SteamId(SteamId64);
   137→		SteamAPICall_t hCall = SteamStats->RequestUserStats(SteamId);
   138→		UserStatsCallResult.Set(hCall, this, &UWjWorldStatsSubsystem::OnSteamUserStatsReceivedCallback);
   139→		UE_LOG(LogWjWorldStats, Log, TEXT("StatsSubsystem: Requested user stats for %s (SteamAPICall=%llu)"), *UserIdStr, hCall);
   140→		return;
   141→	}
   142→#endif
   143→
   144→	// 폴백: 타 유저 스탯은 불가능하므로 빈 데이터로 즉시 완료
   145→	UserStatsCache.FindOrAdd(UserIdStr);
   146→	ReadyUserIds.Add(UserIdStr);
   147→
   148→	OnUserStatsReceived.Broadcast(UserIdStr);
   149→}
