    63→void UWjWorldCosmeticSubsystem::RequestInventoryRefresh()
    64→{
    65→	if (bInventoryRequestPending)
    66→	{
    67→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("인벤토리 요청이 이미 진행 중입니다."));
    68→		return;
    69→	}
    70→
    71→#if WITH_STEAM
    72→	ISteamInventory* SteamInv = SteamInventory();
    73→	if (!SteamInv)
    74→	{
    75→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("Steam Inventory API를 사용할 수 없습니다."));
    76→		return;
    77→	}
    78→
    79→	// 기존 핸들 정리
    80→	if (PendingResultHandle != k_SteamInventoryResultInvalid)
    81→	{
    82→		SteamInv->DestroyResult(PendingResultHandle);
    83→		PendingResultHandle = k_SteamInventoryResultInvalid;
    84→	}
    85→
    86→	if (SteamInv->GetAllItems(&PendingResultHandle))
    87→	{
    88→		bInventoryRequestPending = true;
    89→		StartInventoryPolling();
    90→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("Steam 인벤토리 요청 성공 (ResultHandle: %d)"), PendingResultHandle);
    91→	}
    92→	else
    93→	{
    94→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("Steam 인벤토리 요청 실패"));
    95→	}
    96→#else
    97→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("Steam 미지원 환경 - 인벤토리 갱신 스킵"));
    98→	OnInventoryUpdated.Broadcast();
    99→#endif
   100→}
