   102→bool UWjWorldCosmeticSubsystem::HasItem(FName ItemId) const
   103→{
   104→	return CachedInventory.ContainsByPredicate([ItemId](const FCosmeticItemInstance& Inst)
   105→	{
   106→		return Inst.ItemId == ItemId && Inst.Quantity > 0;
   107→	});
