   109→
   110→void UWjWorldCosmeticSubsystem::GrantItemLocally(FName ItemId, int32 Quantity)
   111→{
   112→	if (ItemId.IsNone() || Quantity <= 0)
   113→	{
   114→		return;
   115→	}
   116→
   117→	// 기존 아이템 수량 증가 또는 새로 추가
   118→	FCosmeticItemInstance* Existing = CachedInventory.FindByPredicate([ItemId](const FCosmeticItemInstance& Inst)
   119→	{
   120→		return Inst.ItemId == ItemId;
   121→	});
   122→
   123→	if (Existing)
   124→	{
   125→		Existing->Quantity += Quantity;
   126→	}
   127→	else
   128→	{
   129→		FCosmeticItemInstance NewItem(ItemId);
   130→		NewItem.Quantity = Quantity;
   131→		CachedInventory.Add(NewItem);
   132→	}
   133→
   134→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("로컬 아이템 부여: %s x%d"), *ItemId.ToString(), Quantity);
   135→	OnInventoryUpdated.Broadcast();
   136→}
