   138→bool UWjWorldCosmeticSubsystem::EquipItem(ECosmeticSlot Slot, FName ItemId)
   139→{
   140→	if (Slot == ECosmeticSlot::None)
   141→	{
   142→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("None 슬롯에 장착할 수 없습니다."));
   143→		return false;
   144→	}
   145→
   146→	if (!HasItem(ItemId))
   147→	{
   148→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("아이템 '%s'을 보유하고 있지 않습니다."), *ItemId.ToString());
   149→		return false;
   150→	}
   151→
   152→	// 카탈로그 검증: 슬롯 일치 확인
